def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    accounts = {}
    history = []
    rejected = []

    arities = {
        "open": 3,
        "deposit": 3,
        "withdraw": 3,
        "transfer": 4,
        "freeze": 2,
        "unfreeze": 2,
        "undo": 1,
    }

    def parse_amount(token):
        if not token or not token.isascii() or not token.isdigit():
            return None

        # Small chunks also support amounts exceeding Python's
        # configurable limit for decimal string conversion.
        value = 0
        for start in range(0, len(token), 18):
            chunk = token[start:start + 18]
            value = value * (10 ** len(chunk)) + int(chunk)
        return value

    for index, operation in enumerate(ops):
        parts = operation.split(" ")
        verb = parts[0]

        if (
            verb not in arities
            or len(parts) != arities[verb]
            or any(part == "" for part in parts)
        ):
            rejected.append(index)
            continue

        if verb == "undo":
            if not history:
                rejected.append(index)
                continue

            for name, previous in history.pop():
                if previous is None:
                    del accounts[name]
                else:
                    accounts[name] = previous
            continue

        if verb in ("open", "deposit", "withdraw", "transfer"):
            amount = parse_amount(parts[-1])
            if amount is None or (verb != "open" and amount == 0):
                rejected.append(index)
                continue

        name = parts[1]
        state = accounts.get(name)

        if verb == "open":
            if state is not None:
                rejected.append(index)
                continue
            changes = {name: (amount, False)}

        elif verb == "deposit":
            if state is None:
                rejected.append(index)
                continue
            changes = {name: (state[0] + amount, state[1])}

        elif verb == "withdraw":
            if state is None or state[1] or state[0] < amount:
                rejected.append(index)
                continue
            changes = {name: (state[0] - amount, state[1])}

        elif verb == "transfer":
            destination = parts[2]
            destination_state = accounts.get(destination)
            if (
                name == destination
                or state is None
                or destination_state is None
                or state[1]
                or state[0] < amount
            ):
                rejected.append(index)
                continue
            changes = {
                name: (state[0] - amount, state[1]),
                destination: (
                    destination_state[0] + amount,
                    destination_state[1],
                ),
            }

        else:
            frozen = verb == "freeze"
            if state is None or state[1] == frozen:
                rejected.append(index)
                continue
            changes = {name: (state[0], frozen)}

        history.append([
            (account, accounts.get(account))
            for account in changes
        ])
        accounts.update(changes)

    return {
        name: state[0] for name, state in accounts.items()
    }, rejected
